async function downloadSalarySlipPDF(slip) {
	(await buildSalarySlipPDF(slip)).save(`Salary_Slip_${slip.memberCode}_${slip.startDate}_to_${slip.endDate}.pdf`);
}
async function printSalarySlipPDF(slip) {
	const doc = await buildSalarySlipPDF(slip);
	doc.autoPrint();
	const blobUrl = String(doc.output("bloburl"));
	const iframe = document.createElement("iframe");
	iframe.style.display = "none";
	iframe.src = blobUrl;
	document.body.appendChild(iframe);
	iframe.onload = () => {
		try {
			iframe.contentWindow?.focus();
			iframe.contentWindow?.print();
		} catch {
			doc.save(`Salary_Slip_${slip.memberCode}_${slip.startDate}_to_${slip.endDate}.pdf`);
		}
		setTimeout(() => {
			iframe.remove();
			URL.revokeObjectURL(blobUrl);
		}, 6e4);
	};
}
